/*{
  "DESCRIPTION": "Gently falling snow with twinkling lights",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "snowColor", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "skyColor", "TYPE": "color", "DEFAULT": [0.0, 0.1, 0.3, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.5 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.1, "MAX": 1.0, "DEFAULT": 0.6 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 3.0, "DEFAULT": 1.5 }
  ]
}*/

float hash(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453123);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);

  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));

  float ab = mix(a, b, f.x);
  float cd = mix(c, d, f.x);
  return mix(ab, cd, f.y);
}

void main() {
  vec2 uv = isf_FragNormCoord;

  float isLine = step(RENDERSIZE.y, 1.5);
  vec2 snowUv = vec2(uv.x, mix(uv.y, uv.x * 0.5, isLine));

  vec2 animated = snowUv * scale;
  animated.y -= TIME * speed * 0.3;

  float n = noise(animated * 8.0);
  float snowPattern = smoothstep(0.4, 0.6, n) * density;

  float twinkle = 0.5 + 0.5 * sin(TIME * 3.0 + hash(floor(animated)) * 6.28);
  snowPattern *= twinkle;

  vec3 finalColor = mix(skyColor.rgb, snowColor.rgb, snowPattern);
  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Fire rising from the bottom with flickering flames",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorBase", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorTip", "TYPE": "color", "DEFAULT": [1.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "intensity", "TYPE": "float", "MIN": 0.0, "MAX": 2.0, "DEFAULT": 1.0 }
  ]
}*/

float hash(float n) {
  return fract(sin(n) * 43758.5453);
}

float noise(float x) {
  float i = floor(x);
  float f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(hash(i), hash(i + 1.0), f);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  float aspectRatio = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);

  vec2 fireUv = uv;
  if (RENDERSIZE.y < 2.0) {
    fireUv = vec2(uv.y * aspectRatio, uv.x);
  }

  float yPos = fireUv.y;
  float xPos = fireUv.x;

  float rise = fract(TIME * speed * 0.5 - yPos);
  float flicker = noise(xPos * 8.0 + TIME * speed * 2.0) * 0.5 + 0.5;
  float wobble = sin(xPos * 3.14159 + TIME * speed) * 0.1 + 0.5;

  float fireNoise = noise(xPos * 4.0 + rise * 3.0) * flicker * wobble;
  float flameMask = smoothstep(0.0, 0.4, yPos) * smoothstep(1.2, 0.3, yPos + rise);
  flameMask = flameMask * (fireNoise + 0.3);

  float gradient = smoothstep(0.0, 1.0, yPos);
  vec3 fireColor = mix(colorBase.rgb, colorTip.rgb, gradient);

  vec3 finalColor = fireColor * flameMask * intensity;

  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Candy cane stripes scrolling diagonally across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "stripeWidth", "TYPE": "float", "MIN": 0.05, "MAX": 0.5, "DEFAULT": 0.1 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float diagonal = uv.x + uv.y - TIME * speed * 0.5;
  float pattern = fract(diagonal / stripeWidth);
  float stripe = step(0.5, pattern);

  vec3 color = mix(colorA.rgb, colorB.rgb, stripe);
  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Smooth color wash that fades between user palette colors",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 }
  ]
}*/

void main() {
  float phase = mod(TIME * speed * 0.5, 3.0);
  vec3 color = vec3(0.0);

  if (phase < 1.0) {
    color = mix(colorA.rgb, colorB.rgb, smoothstep(0.0, 1.0, phase));
  } else if (phase < 2.0) {
    color = mix(colorB.rgb, colorC.rgb, smoothstep(1.0, 2.0, phase));
  } else {
    color = mix(colorC.rgb, colorA.rgb, smoothstep(2.0, 3.0, phase));
  }

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Twinkling stars scattered across the display with varying brightness",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "starColor", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "backgroundColor", "TYPE": "color", "DEFAULT": [0.0, 0.0, 0.2, 1.0] },
    { "NAME": "twinkleSpeed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 2.0 },
    { "NAME": "starDensity", "TYPE": "float", "MIN": 0.1, "MAX": 1.0, "DEFAULT": 0.3 }
  ]
}*/

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  vec3 finalColor = backgroundColor.rgb;

  for (int i = 0; i < 16; i++) {
    float fi = float(i);
    vec2 starPos = fract(vec2(
      sin(fi * 0.1 + 1.23) * 0.5 + 0.5,
      cos(fi * 0.15 + 4.56) * 0.5 + 0.5
    ));

    vec2 diff = uv - starPos;
    float dist = length(diff);

    float randomSeed = hash(starPos);
    if (randomSeed < starDensity) {
      float twinkle = sin(TIME * twinkleSpeed + randomSeed * 6.28) * 0.5 + 0.5;
      twinkle = twinkle * twinkle;

      float brightness = smoothstep(0.015, 0.0, dist) * twinkle;
      finalColor = mix(finalColor, starColor.rgb, brightness);
    }
  }

  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Chasing light that runs smoothly along the roofline",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "width", "TYPE": "float", "MIN": 0.01, "MAX": 0.5, "DEFAULT": 0.1 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float isRoofline = step(RENDERSIZE.y, 2.0);
  float coord = mix(uv.x, uv.y, isRoofline);

  float chase = fract(coord - TIME * speed * 0.5);
  float pulse = smoothstep(width + 0.05, 0.0, abs(chase - 0.5) - 0.25);

  vec3 color = mix(colorA.rgb, colorB.rgb, step(0.5, chase));
  vec3 final = mix(color * 0.2, color, pulse);

  gl_FragColor = vec4(final, 1.0);
}

/*{
  "DESCRIPTION": "Swirling plasma effect with animated color vortex",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.5, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 8.0, "DEFAULT": 3.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord - 0.5;

  float angle = atan(uv.y, uv.x);
  float radius = length(uv);

  float plasma = sin(angle * 3.0 + TIME * speed) * 0.5 + 0.5;
  plasma += sin(radius * scale - TIME * speed * 0.7) * 0.5 + 0.5;
  plasma += sin((angle + radius) * 2.0 + TIME * speed * 0.5) * 0.5 + 0.5;

  plasma = mod(plasma, 3.0) / 3.0;

  vec3 color;
  if (plasma < 0.5) {
    color = mix(colorA.rgb, colorB.rgb, plasma * 2.0);
  } else {
    color = mix(colorB.rgb, colorC.rgb, (plasma - 0.5) * 2.0);
  }

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Rainbow colors sweep across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "width", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.3 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float h = mod(uv.x - TIME * speed * 0.5 + uv.y * width, 1.0);

  vec3 col = vec3(0.0);

  if (h < 0.166666) {
    col = mix(vec3(1.0, 0.0, 0.0), vec3(1.0, 0.5, 0.0), (h / 0.166666));
  } else if (h < 0.333333) {
    col = mix(vec3(1.0, 0.5, 0.0), vec3(1.0, 1.0, 0.0), ((h - 0.166666) / 0.166666));
  } else if (h < 0.5) {
    col = mix(vec3(1.0, 1.0, 0.0), vec3(0.0, 1.0, 0.0), ((h - 0.333333) / 0.166666));
  } else if (h < 0.666666) {
    col = mix(vec3(0.0, 1.0, 0.0), vec3(0.0, 0.0, 1.0), ((h - 0.5) / 0.166666));
  } else if (h < 0.833333) {
    col = mix(vec3(0.0, 0.0, 1.0), vec3(0.7, 0.0, 1.0), ((h - 0.666666) / 0.166666));
  } else {
    col = mix(vec3(0.7, 0.0, 1.0), vec3(1.0, 0.0, 0.0), ((h - 0.833333) / 0.166666));
  }

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "All lights pulse together to a steady beat",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.5, "MAX": 4.0, "DEFAULT": 2.0 },
    { "NAME": "intensity", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.8 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float pulse = abs(sin(TIME * speed * 3.14159265));
  pulse = mix(1.0 - intensity, 1.0, pulse);

  vec3 color = mix(colorA.rgb, colorB.rgb, 0.5);
  color = color * pulse;

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "American flag waving in the wind with stars and stripes",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "waveAmplitude", "TYPE": "float", "MIN": 0.0, "MAX": 0.3, "DEFAULT": 0.1 },
    { "NAME": "waveFrequency", "TYPE": "float", "MIN": 0.5, "MAX": 4.0, "DEFAULT": 2.0 },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 1.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float waveOffset = sin(uv.y * waveFrequency * 3.14159 + TIME * speed) * waveAmplitude;
  float distortedX = uv.x + waveOffset;

  vec3 color = vec3(0.0);

  if (distortedX < 0.0 || distortedX > 1.0) {
    color = vec3(0.0);
  } else if (distortedX < 0.2) {
    float starY = mod(uv.y * 9.0, 1.0);
    float starX = mod(distortedX * 45.0, 1.0);
    float star = step(0.8, starX) * step(0.8, starY);
    color = mix(vec3(0.0, 0.0, 0.3), vec3(1.0, 1.0, 1.0), star);
  } else {
    float stripeIndex = mod(floor(uv.y * 13.0), 2.0);
    if (stripeIndex < 0.5) {
      color = vec3(1.0, 0.0, 0.0);
    } else {
      color = vec3(1.0, 1.0, 1.0);
    }
  }

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Spooky green fog drifting across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "fogColor", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.0, "MAX": 2.0, "DEFAULT": 1.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float fog = 0.0;

  for (int i = 0; i < 8; i++) {
    float layer = float(i) * 0.125;
    float wave = sin(uv.x * 3.0 + TIME * speed * 0.5 + layer * 6.28) * 0.5 + 0.5;
    wave *= cos(uv.y * 2.0 + TIME * speed * 0.3 + layer * 3.14) * 0.5 + 0.5;
    fog += wave * (1.0 - layer) * 0.125;
  }

  fog = pow(fog, 1.0 / (density + 0.5));
  fog = smoothstep(0.1, 0.8, fog);

  vec3 finalColor = mix(vec3(0.0), fogColor.rgb, fog);
  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Spinning tunnel effect with color-shifting rings",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "scale", "TYPE": "float", "MIN": 1.0, "MAX": 20.0, "DEFAULT": 8.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord - vec2(0.5, 0.5);

  float dist = length(uv);
  float angle = atan(uv.y, uv.x);

  float tunnel = 1.0 / (dist + 0.1);

  float depth = fract(dist * scale - TIME * speed);
  float rings = step(0.5, fract(depth * 3.0));

  float spin = angle + TIME * speed * 2.0;
  float rotated = mod(spin, 6.28318530718);

  vec3 col = mix(colorA.rgb, colorB.rgb, step(3.14159265359, rotated));
  col = mix(col, colorC.rgb, step(0.5, fract(rotated / 3.14159265359)));

  col = col * (0.5 + 0.5 * rings) * clamp(tunnel * 0.3, 0.0, 1.0);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Ocean waves rolling across the display with foam crests",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorDeep", "TYPE": "color", "DEFAULT": [0.0, 0.2, 0.6, 1.0] },
    { "NAME": "colorShallow", "TYPE": "color", "DEFAULT": [0.0, 0.8, 1.0, 1.0] },
    { "NAME": "colorFoam", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "waveScale", "TYPE": "float", "MIN": 0.5, "MAX": 8.0, "DEFAULT": 3.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  // Determine if this is a thin vertical line or normal canvas
  float timeOffset = TIME * speed * 0.5;
  float waveY;

  if (RENDERSIZE.y < 2.0) {
    // Roofline: animate along x instead of y
    waveY = sin((uv.x - timeOffset) * waveScale * 6.28318) * 0.3 + 0.5;
  } else {
    // Normal canvas: waves roll across horizontally
    waveY = sin((uv.x - timeOffset) * waveScale * 6.28318) * 0.4 + 0.5;
  }

  // Calculate wave envelope - peak gets narrower
  float waveDistance = abs(uv.y - waveY);
  float wavePeak = smoothstep(0.15, 0.0, waveDistance);
  float waveBody = smoothstep(0.35, 0.0, waveDistance);

  // Foam appears at wave crests
  float foam = wavePeak * (0.5 + 0.5 * sin(uv.x * 12.0 + TIME * speed * 3.0));

  // Color based on depth: deep blue at bottom, shallow cyan higher up
  vec3 waterColor = mix(colorDeep.rgb, colorShallow.rgb, uv.y);

  // Blend wave brightness and foam
  vec3 finalColor = mix(waterColor, colorShallow.rgb, waveBody * 0.6);
  finalColor = mix(finalColor, colorFoam.rgb, foam * 0.8);

  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Slow lava lamp blobs flowing and morphing in mesmerizing patterns",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.5, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 2.0, "DEFAULT": 0.3 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 3.0, "DEFAULT": 1.5 }
  ]
}*/

float noise(vec2 p) {
  return fract(sin(p.x * 12.9898 + p.y * 78.233) * 43758.5453);
}

float smoothNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);

  float n00 = noise(i);
  float n10 = noise(i + vec2(1.0, 0.0));
  float n01 = noise(i + vec2(0.0, 1.0));
  float n11 = noise(i + vec2(1.0, 1.0));

  float nx0 = mix(n00, n10, f.x);
  float nx1 = mix(n01, n11, f.x);
  return mix(nx0, nx1, f.y);
}

void main() {
  vec2 uv = isf_FragNormCoord;

  float t = TIME * speed;

  vec2 p = uv * scale;
  p.x += sin(t * 0.4) * 0.3;
  p.y += cos(t * 0.3) * 0.3;

  float blob1 = smoothNoise(p + vec2(t * 0.2, sin(t * 0.15) * 0.2));
  float blob2 = smoothNoise(p + vec2(cos(t * 0.25) * 0.3, t * 0.15));
  float blob3 = smoothNoise(p * 0.7 + vec2(sin(t * 0.35) * 0.4, cos(t * 0.2) * 0.3));

  float combined = blob1 * 0.4 + blob2 * 0.35 + blob3 * 0.25;
  combined = smoothstep(0.3, 0.7, combined);

  float flow = fract(uv.y - t * 0.1);
  combined *= mix(0.7, 1.0, smoothstep(0.0, 0.5, flow) * smoothstep(1.0, 0.5, flow));

  vec3 color = mix(colorA.rgb, colorB.rgb, sin(t * 0.2 + uv.y * 3.0) * 0.5 + 0.5);
  color *= combined;

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Alternating flashes between two colors",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 2.0 }
  ]
}*/
void main() {
  float flashCycle = mod(TIME * speed, 2.0);
  float flash = step(1.0, flashCycle);
  vec3 color = mix(colorA.rgb, colorB.rgb, flash);
  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Green streaks falling like digital rain across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 0.5, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "density", "TYPE": "float", "MIN": 1.0, "MAX": 20.0, "DEFAULT": 8.0 },
    { "NAME": "streakLength", "TYPE": "float", "MIN": 0.05, "MAX": 0.5, "DEFAULT": 0.2 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  // For roofline displays, use x-axis when height is minimal
  vec2 coord = (RENDERSIZE.y < 2.0) ? vec2(uv.y, uv.x) : uv;

  // Create falling streaks using modulo for seamless looping
  float fall = mod(coord.y + TIME * speed, 1.0);

  // Hash-like pattern for multiple independent streaks
  float streamPos = floor(coord.x * density);
  float streamSeed = fract(sin(streamPos * 12.9898) * 43758.5453);

