    float fade = (1.0 - burstTime) * (1.0 - burstTime);

    vec3 burstColor = fireworkColor(hash(id * 11.0));
    result += burstColor * trailWidth * fade;
  }

  // Clamp and output
  result = min(result, vec3(1.0));
  gl_FragColor = vec4(result, 1.0);
}

